package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One money-making job, loaded from recipes.txt.
 * Quantities can be fractions, e.g. 0.05 of a rare drop per kill.
 */
public class Recipe
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(Recipe.class);

	private final String category;
	private final String name;
	/** RuneLite Skill enum name, or "NONE". This is the skill used for the next-level planner. */
	private final String skill;
	private final int level;
	private final boolean members;
	private final double perHour;
	/** Coins paid per action (fees). Negative means coins received, e.g. from pickpocketing. */
	private final double coinsPerAction;
	private final List<Stack> inputs;
	private final List<Stack> outputs;
	private final double xp;
	/** Every skill level needed, including the main one. */
	private final List<Req> reqs;
	/** What one action is, e.g. "kill", "fish", "min". */
	private final String unit;
	/** OSRS Wiki guide for this method, or empty. */
	private final String url;

	public Recipe(String category, String name, String skill, int level, boolean members, double perHour,
		double coinsPerAction, List<Stack> inputs, List<Stack> outputs, double xp, List<Req> reqs, String unit, String url)
	{
		this.category = category;
		this.name = name;
		this.skill = skill;
		this.level = level;
		this.members = members;
		this.perHour = perHour;
		this.coinsPerAction = coinsPerAction;
		this.inputs = inputs;
		this.outputs = outputs;
		this.xp = xp;
		this.reqs = reqs;
		this.unit = unit;
		this.url = url;
	}

	public String getCategory()
	{
		return category;
	}

	public String getName()
	{
		return name;
	}

	public String getSkill()
	{
		return skill;
	}

	public boolean hasSkill()
	{
		return !"NONE".equals(skill);
	}

	public int getLevel()
	{
		return level;
	}

	public boolean isMembers()
	{
		return members;
	}

	public double getPerHour()
	{
		return perHour;
	}

	public double getCoinsPerAction()
	{
		return coinsPerAction;
	}

	public List<Stack> getInputs()
	{
		return inputs;
	}

	public List<Stack> getOutputs()
	{
		return outputs;
	}

	public double getXp()
	{
		return xp;
	}

	public List<Req> getReqs()
	{
		return reqs;
	}

	public String getUnit()
	{
		return unit;
	}

	public String getUrl()
	{
		return url;
	}

	/** An item name and how many of it. */
	public static class Stack
	{
		private final String item;
		private final double qty;

		public Stack(String item, double qty)
		{
			this.item = item;
			this.qty = qty;
		}

		public String getItem()
		{
			return item;
		}

		public double getQty()
		{
			return qty;
		}
	}

	/** A skill level requirement. */
	public static class Req
	{
		private final String skill;
		private final int level;

		public Req(String skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}

		public String getSkill()
		{
			return skill;
		}

		public int getLevel()
		{
			return level;
		}
	}

	/**
	 * Parse recipes.txt:
	 * category|name|skill|level|members|perHour|coins|inputs|outputs|xp[|reqs|unit|url]
	 * where reqs is "SKILL:level;SKILL:level".
	 */
	public static List<Recipe> load(InputStream in) throws IOException
	{
		List<Recipe> list = new ArrayList<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] f = line.split("\\|", -1);
				if (f.length < 10)
				{
					continue;
				}
				try
				{
					list.add(parse(f));
				}
				catch (RuntimeException e)
				{
					log.warn("Skipping a recipes.txt line that couldn't be read: {}", line, e);
				}
			}
		}
		return Collections.unmodifiableList(list);
	}

	private static Recipe parse(String[] f)
	{
		String skill = f[2];
		int level = Integer.parseInt(f[3]);
		List<Req> reqs = new ArrayList<>();
		if (!"NONE".equals(skill))
		{
			reqs.add(new Req(skill, level));
		}
		if (f.length > 10)
		{
			for (String part : f[10].split(";"))
			{
				int colon = part.indexOf(':');
				if (colon > 0)
				{
					String s = part.substring(0, colon);
					if (!s.equals(skill))
					{
						reqs.add(new Req(s, Integer.parseInt(part.substring(colon + 1))));
					}
				}
			}
		}
		return new Recipe(f[0], f[1], skill, level, "1".equals(f[4]),
			Double.parseDouble(f[5]), Double.parseDouble(f[6]), stacks(f[7]), stacks(f[8]), Double.parseDouble(f[9]),
			Collections.unmodifiableList(reqs), f.length > 11 ? f[11] : "", f.length > 12 ? f[12] : "");
	}

	static List<Stack> stacks(String s)
	{
		List<Stack> out = new ArrayList<>();
		for (String part : s.split(";"))
		{
			if (part.isEmpty())
			{
				continue;
			}
			int star = part.lastIndexOf('*');
			out.add(new Stack(part.substring(0, star), Double.parseDouble(part.substring(star + 1))));
		}
		return Collections.unmodifiableList(out);
	}
}

package com.moneymaker.data;

import java.util.concurrent.atomic.AtomicLong;

/**
 * Stops the manual Refresh button from hammering the wiki prices API:
 * a fetch is only allowed once {@link #COOLDOWN_MS} has passed since the last one started.
 */
public final class RefreshCooldown
{
	public static final long COOLDOWN_MS = 60_000L;

	private final AtomicLong lastFetch = new AtomicLong(Long.MIN_VALUE / 2);

	/** Note that a fetch is starting now (scheduled or manual). */
	public void markFetch(long now)
	{
		lastFetch.set(now);
	}

	/** Whole seconds still to wait before a manual refresh is allowed; 0 means go ahead. */
	public long secondsLeft(long now)
	{
		long left = COOLDOWN_MS - (now - lastFetch.get());
		return left <= 0 ? 0 : (left + 999) / 1000;
	}
}

package com.moneymaker.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** XP training methods and milestone levels for every skill, loaded from training.txt, plus a route planner. */
public class Training
{
	private static final int[] XP = new int[100];

	static
	{
		// standard OSRS experience table
		double points = 0;
		for (int lvl = 1; lvl < 100; lvl++)
		{
			XP[lvl] = (int) Math.floor(points / 4);
			points += Math.floor(lvl + 300 * Math.pow(2, lvl / 7.0));
		}
	}

	/** XP needed to reach a level (1-99). */
	public static int xpForLevel(int level)
	{
		return XP[Math.max(1, Math.min(99, level))];
	}

	/** Level for an amount of XP. */
	public static int levelForXp(long xp)
	{
		int lvl = 1;
		while (lvl < 99 && XP[lvl + 1] <= xp)
		{
			lvl++;
		}
		return lvl;
	}

	private final Map<String, List<Method>> methods;
	private final Map<String, List<Milestone>> milestones;

	private Training(Map<String, List<Method>> methods, Map<String, List<Milestone>> milestones)
	{
		this.methods = methods;
		this.milestones = milestones;
	}

	public static Training empty()
	{
		return new Training(Collections.emptyMap(), Collections.emptyMap());
	}

	public List<String> getSkills()
	{
		return new ArrayList<>(methods.keySet());
	}

	public List<Method> getMethods(String skill)
	{
		return methods.getOrDefault(skill, Collections.emptyList());
	}

	public List<Milestone> getMilestones(String skill)
	{
		return milestones.getOrDefault(skill, Collections.emptyList());
	}

	/** A level that unlocks something worth aiming for. */
	public static class Milestone
	{
		private final int level;
		private final String text;

		Milestone(int level, String text)
		{
			this.level = level;
			this.text = text;
		}

		public int getLevel()
		{
			return level;
		}

		public String getText()
		{
			return text;
		}
	}

	/** One way to train a skill. */
	public static class Method
	{
		private final String skill;
		private final String name;
		private final int level;
		private final double xpAtMin;
		private final double xpAt99;
		private final double xpEach;
		private final String unit;
		private final boolean ironman;
		private final boolean members;
		private final boolean intense;
		private final int cycleMinutes;
		private final List<Recipe.Stack> needs;
		private final List<Recipe.Stack> gives;
		private final String requirements;
		private final String note;

		Method(String[] f)
		{
			skill = f[1];
			name = f[2];
			level = Integer.parseInt(f[3]);
			xpAtMin = Double.parseDouble(f[4]);
			xpAt99 = Double.parseDouble(f[5]);
			xpEach = Double.parseDouble(f[6]);
			unit = f[7];
			ironman = "1".equals(f[8]);
			members = "1".equals(f[9]);
			intense = "1".equals(f[10]);
			cycleMinutes = Integer.parseInt(f[11]);
			needs = Recipe.stacks(f[12]);
			gives = Recipe.stacks(f[13]);
			requirements = f[14];
			note = f[15];
		}

		public String getSkill()
		{
			return skill;
		}

		public String getName()
		{
			return name;
		}

		public int getLevel()
		{
			return level;
		}

		/** Typical xp per hour at a level (interpolated between the method's level and 99). */
		public double xpPerHour(int atLevel)
		{
			if (level >= 99)
			{
				return xpAt99;
			}
			double t = Math.max(0, Math.min(1, (atLevel - level) / (double) (99 - level)));
			return xpAtMin + (xpAt99 - xpAtMin) * t;
		}

		/** For ranking: xp per real hour (timed runs are limited by how often you can do them). */
		double effectiveRate(int atLevel)
		{
			return cycleMinutes > 0 && xpEach > 0 ? xpEach * 60.0 / cycleMinutes : xpPerHour(atLevel);
		}

		public double getXpEach()
		{
			return xpEach;
		}

		public String getUnit()
		{
			return unit.isEmpty() ? "action" : unit;
		}

		public boolean isIronman()
		{
			return ironman;
		}

		public boolean isMembers()
		{
			return members;
		}

		public boolean isIntense()
		{
			return intense;
		}

		/** For timed methods (farm runs): minutes between runs, else 0. */
		public int getCycleMinutes()
		{
			return cycleMinutes;
		}

		public List<Recipe.Stack> getNeeds()
		{
			return needs;
		}

		public List<Recipe.Stack> getGives()
		{
			return gives;
		}

		public String getRequirements()
		{
			return requirements;
		}

		public String getNote()
		{
			return note;
		}
	}

	/** Which methods the planner may use. */
	public static class Filter
	{
		public boolean ironman;
		public boolean members = true;
		public boolean intense = true;
		/** Only methods that don't use up supplies. */
		public boolean noSupplies;
		/** Only timed methods (farm runs); they're ranked by xp per real hour. */
		public boolean timedOnly;

		boolean allows(Method m)
		{
			return (!ironman || m.ironman) && (members || !m.members) && (intense || !m.intense)
				&& (!noSupplies || m.needs.isEmpty()) && (!timedOnly || m.cycleMinutes > 0);
		}
	}

	/** One stretch of the route: levels from-to with one method. */
	public static class Step
	{
		private final Method method;
		private final int fromLevel;
		private int toLevel;
		private double xp;
		private double hours;

		Step(Method method, int fromLevel)
		{
			this.method = method;
			this.fromLevel = fromLevel;
			this.toLevel = fromLevel;
		}

		public Method getMethod()
		{
			return method;
		}

		public int getFromLevel()
		{
			return fromLevel;
		}

		public int getToLevel()
		{
			return toLevel;
		}

		public double getXp()
		{
			return xp;
		}

		/** Hours of play. */
		public double getHours()
		{
			return hours;
		}

		/** Actions (kills, logs, casts, runs...), or 0 when the method has no per-action xp. */
		public long getActions()
		{
			return method.xpEach > 0 ? (long) Math.ceil(xp / method.xpEach) : 0;
		}

		/** For timed methods: real days if you do one run every cycle. */
		public double getDays()
		{
			return method.cycleMinutes > 0 ? getActions() * method.cycleMinutes / 1440.0 : 0;
		}
	}

	/**
	 * Fastest route from the current xp to a target level: at every level, use the best method you can.
	 * Returns an empty list if nothing is available.
	 */
	public List<Step> plan(String skill, long fromXp, int toLevel, Filter filter)
	{
		List<Step> steps = new ArrayList<>();
		long xp = fromXp;
		long target = xpForLevel(toLevel);
		Step current = null;
		while (xp < target)
		{
			int lvl = levelForXp(xp);
			long next = Math.min(target, xpForLevel(lvl + 1));
			Method best = best(skill, lvl, filter);
			if (best == null)
			{
				break;
			}
			double rate = best.xpPerHour(lvl);
			if (rate <= 0)
			{
				break;
			}
			if (current == null || current.method != best)
			{
				current = new Step(best, lvl);
				steps.add(current);
			}
			current.xp += next - xp;
			current.hours += (next - xp) / rate;
			current.toLevel = levelForXp(next);
			xp = next;
		}
		return steps;
	}

	/** The fastest method available at a level, or null. */
	public Method best(String skill, int level, Filter filter)
	{
		Method best = null;
		for (Method m : getMethods(skill))
		{
			if (m.level <= level && filter.allows(m) && (best == null || m.effectiveRate(level) > best.effectiveRate(level)))
			{
				best = m;
			}
		}
		return best;
	}

	/** Parse training.txt. */
	public static Training load(InputStream in) throws IOException
	{
		Map<String, List<Method>> methods = new LinkedHashMap<>();
		Map<String, List<Milestone>> milestones = new LinkedHashMap<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				String[] f = line.split("\\|", -1);
				try
				{
					if ("M".equals(f[0]) && f.length >= 4)
					{
						Milestone m = new Milestone(Integer.parseInt(f[2]), f[3]);
						milestones.computeIfAbsent(f[1], k -> new ArrayList<>()).add(m);
					}
					else if ("T".equals(f[0]) && f.length >= 16)
					{
						Method m = new Method(f);
						methods.computeIfAbsent(f[1], k -> new ArrayList<>()).add(m);
					}
				}
				catch (RuntimeException e)
				{
					org.slf4j.LoggerFactory.getLogger(Training.class).warn("Skipping a training.txt line that couldn't be read: {}", line, e);
				}
			}
		}
		milestones.values().forEach(l -> l.sort((a, b) -> Integer.compare(a.level, b.level)));
		return new Training(methods, milestones);
	}
}

package com.moneymaker.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Client for the OSRS Wiki real-time prices API (https://prices.runescape.wiki).
 * The wiki asks for a descriptive User-Agent, so we send one.
 */
@Singleton
public class WikiPriceClient
{
	private static final HttpUrl BASE = HttpUrl.parse("https://prices.runescape.wiki/api/v1/osrs/");
	private static final String USER_AGENT = "RuneLite Adventurer's Ledger plugin - github.com/phattymatty10107-cmd/adventurers-ledger";

	private static final Type MAPPING_TYPE = new TypeToken<List<Mapping>>()
	{
	}.getType();

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	public WikiPriceClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	public List<Mapping> fetchMapping() throws IOException
	{
		List<Mapping> list = get("mapping", MAPPING_TYPE);
		return list == null ? Collections.emptyList() : list;
	}

	public Map<Integer, Latest> fetchLatest() throws IOException
	{
		LatestResponse r = get("latest", LatestResponse.class);
		return r == null || r.data == null ? Collections.emptyMap() : r.data;
	}

	/** Average prices and volumes over the last hour. */
	public Map<Integer, Average> fetchHourly() throws IOException
	{
		return fetchAverage("1h");
	}

	/** Average prices and volumes over the last 24 hours. */
	public Map<Integer, Average> fetchDaily() throws IOException
	{
		return fetchAverage("24h");
	}

	private Map<Integer, Average> fetchAverage(String path) throws IOException
	{
		AverageResponse r = get(path, AverageResponse.class);
		return r == null || r.data == null ? Collections.emptyMap() : r.data;
	}

	private <T> T get(String path, Type type) throws IOException
	{
		Request request = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment(path).build())
			.header("User-Agent", USER_AGENT)
			.build();

		try (Response response = http.newCall(request).execute())
		{
			ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				throw new IOException("OSRS Wiki returned HTTP " + response.code() + " for /" + path);
			}
			return gson.fromJson(body.charStream(), type);
		}
	}

	public static class Mapping
	{
		public int id;
		public String name;
		public boolean members;
		public Integer limit;
	}

	public static class Latest
	{
		public Long high;
		public Long highTime;
		public Long low;
		public Long lowTime;
	}

	public static class Average
	{
		public Long avgHighPrice;
		public Long highPriceVolume;
		public Long avgLowPrice;
		public Long lowPriceVolume;
	}

	private static class LatestResponse
	{
		Map<Integer, Latest> data;
	}

	private static class AverageResponse
	{
		Map<Integer, Average> data;
	}
}

package com.moneymaker.route;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

/**
 * Which tiles you can walk between. Read from collision-map.zip, the map data made for the
 * Shortest Path plugin (github.com/Skretzo/shortest-path, BSD 2-Clause): one entry per 64x64 map
 * region, holding four bits per tile on each plane. Bit 0 is "can step north", bit 1 "can step east".
 */
public final class CollisionMap
{
	private static final int REGION = 64;
	private static final int FLAGS = 4;
	private static final int NORTH = 0;
	private static final int EAST = 1;

	private final int minRx;
	private final int minRy;
	private final int width;
	private final int height;
	/** One array of bits per region, or null where there's no map. */
	private final long[][] regions;

	private CollisionMap(int minRx, int minRy, int width, int height, long[][] regions)
	{
		this.minRx = minRx;
		this.minRy = minRy;
		this.width = width;
		this.height = height;
		this.regions = regions;
	}

	public static CollisionMap load(InputStream in) throws IOException
	{
		Map<Integer, long[]> byRegion = new HashMap<>();
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = 0;
		int maxY = 0;
		try (ZipInputStream zip = new ZipInputStream(in))
		{
			ZipEntry entry;
			byte[] buf = new byte[8192];
			while ((entry = zip.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				if (n.length != 2)
				{
					continue;
				}
				int rx;
				int ry;
				try
				{
					rx = Integer.parseInt(n[0]);
					ry = Integer.parseInt(n[1]);
				}
				catch (NumberFormatException e)
				{
					continue;
				}
				ByteArrayOutputStream out = new ByteArrayOutputStream(8192);
				int read;
				while ((read = zip.read(buf)) > 0)
				{
					out.write(buf, 0, read);
				}
				byte[] bytes = out.toByteArray();
				long[] words = new long[(bytes.length + 7) / 8];
				ByteBuffer bb = ByteBuffer.wrap(java.util.Arrays.copyOf(bytes, words.length * 8)).order(ByteOrder.LITTLE_ENDIAN);
				for (int i = 0; i < words.length; i++)
				{
					words[i] = bb.getLong();
				}
				byRegion.put(rx | (ry << 16), words);
				minX = Math.min(minX, rx);
				minY = Math.min(minY, ry);
				maxX = Math.max(maxX, rx);
				maxY = Math.max(maxY, ry);
			}
		}
		if (byRegion.isEmpty())
		{
			throw new IOException("The collision map is empty");
		}
		int w = maxX - minX + 1;
		int h = maxY - minY + 1;
		long[][] regions = new long[w * h][];
		for (Map.Entry<Integer, long[]> e : byRegion.entrySet())
		{
			int rx = e.getKey() & 0xFFFF;
			int ry = e.getKey() >>> 16;
			regions[(rx - minX) + (ry - minY) * w] = e.getValue();
		}
		return new CollisionMap(minX, minY, w, h, regions);
	}

	private boolean get(int x, int y, int z, int flag)
	{
		int rx = (x >> 6) - minRx;
		int ry = (y >> 6) - minRy;
		if (rx < 0 || ry < 0 || rx >= width || ry >= height)
		{
			return false;
		}
		long[] words = regions[rx + ry * width];
		if (words == null)
		{
			return false;
		}
		int bit = (z * REGION * REGION + (y & 63) * REGION + (x & 63)) * FLAGS + flag;
		int word = bit >> 6;
		return word < words.length && (words[word] >>> (bit & 63) & 1L) != 0;
	}

	public boolean n(int x, int y, int z)
	{
		return get(x, y, z, NORTH);
	}

	public boolean s(int x, int y, int z)
	{
		return get(x, y - 1, z, NORTH);
	}

	public boolean e(int x, int y, int z)
	{
		return get(x, y, z, EAST);
	}

	public boolean w(int x, int y, int z)
	{
		return get(x - 1, y, z, EAST);
	}

	/** True when you can't step off this tile in any direction (a wall, water, or off the map). */
	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	public boolean isBlocked(int p)
	{
		return isBlocked(Pos.x(p), Pos.y(p), Pos.plane(p));
	}

	/**
	 * The tiles you can step to from here, as a bit per direction: N, NE, E, SE, S, SW, W, NW.
	 * A diagonal is only open when both ways round the corner are.
	 */
	public int moves(int x, int y, int z)
	{
		boolean n = n(x, y, z);
		boolean s = s(x, y, z);
		boolean e = e(x, y, z);
		boolean w = w(x, y, z);
		int mask = 0;
		if (n)
		{
			mask |= 1;
			if (e && e(x, y + 1, z) && n(x + 1, y, z))
			{
				mask |= 2;
			}
			if (w && w(x, y + 1, z) && n(x - 1, y, z))
			{
				mask |= 128;
			}
		}
		if (e)
		{
			mask |= 4;
		}
		if (s)
		{
			mask |= 16;
			if (e && e(x, y - 1, z) && s(x + 1, y, z))
			{
				mask |= 8;
			}
			if (w && w(x, y - 1, z) && s(x - 1, y, z))
			{
				mask |= 32;
			}
		}
		if (w)
		{
			mask |= 64;
		}
		return mask;
	}
}

package com.moneymaker.route;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Finds the quickest way between two tiles: walking over the collision map, plus the doors,
 * boats, fairy rings and teleports this character can use. Plain Dijkstra, where a tile walked
 * costs 1 and a transport costs the game ticks it takes.
 */
public final class Pathfinder
{
	/** Give up after this many tiles; the whole walkable world is under this. */
	private static final int MAX_TILES = 12_000_000;
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};
	/** Extra cost for using any teleport, so a two-tile saving doesn't burn a teleport. */
	private static final int TELEPORT_PENALTY = 10;
	/** How far from the place asked for to look for somewhere to stand, when the tile itself is solid. */
	private static final int SNAP_RADIUS = 6;
	/** Ending this close to a place that can't be stood on counts as getting there. */
	private static final int NEAR_ENOUGH = 6;

	private final CollisionMap map;
	private final TransportData transports;

	public Pathfinder(CollisionMap map, TransportData transports)
	{
		this.map = map;
		this.transports = transports;
	}

	/**
	 * The quickest route from start to the nearest of the targets, or null if start isn't on the map.
	 * When none of the targets can be reached the route ends as close to the first one as it can get.
	 */
	public Route find(int start, Collection<Integer> wanted, PlayerState state)
	{
		if (wanted.isEmpty())
		{
			return null;
		}
		Set<Integer> targets = new HashSet<>();
		int first = Pos.NONE;
		for (int w : wanted)
		{
			if (first == Pos.NONE)
			{
				first = w;
			}
			targets.addAll(standable(w));
		}
		boolean wildOk = !state.avoidWilderness || Pos.wildernessLevel(start) > 0;
		for (int t : wanted)
		{
			wildOk |= Pos.wildernessLevel(t) > 0;
		}

		Grid cost = new Grid(Integer.MAX_VALUE);
		Grid prev = new Grid(Pos.NONE);
		Map<Integer, Transport> via = new HashMap<>();
		Heap heap = new Heap();
		cost.set(start, 0);
		heap.push(0, start);

		// teleports work from where you stand
		int startWild = Pos.wildernessLevel(start);
		for (Transport t : transports.teleports())
		{
			if (startWild > Math.max(0, t.maxWilderness) || !t.available(state))
			{
				continue;
			}
			if (!wildOk && Pos.wildernessLevel(t.destination) > 0)
			{
				continue;
			}
			int c = Math.max(1, t.duration) + TELEPORT_PENALTY;
			if (c < cost.get(t.destination))
			{
				cost.set(t.destination, c);
				prev.set(t.destination, start);
				via.put(t.destination, t);
				heap.push(c, t.destination);
			}
		}

		int best = start;
		long bestScore = score(start, first);
		int end = Pos.NONE;
		int settled = 0;
		while (!heap.isEmpty())
		{
			long top = heap.pop();
			int node = (int) top;
			int c = (int) (top >>> 32);
			if (c > cost.get(node))
			{
				continue;
			}
			if (targets.contains(node))
			{
				end = node;
				break;
			}
			if (++settled > MAX_TILES)
			{
				break;
			}
			long sc = score(node, first);
			if (sc < bestScore)
			{
				bestScore = sc;
				best = node;
			}
			int x = Pos.x(node);
			int y = Pos.y(node);
			int z = Pos.plane(node);
			int moves = map.moves(x, y, z);
			for (int d = 0; d < 8; d++)
			{
				if ((moves & (1 << d)) == 0)
				{
					continue;
				}
				int next = Pos.pack(x + DX[d], y + DY[d], z);
				if (!wildOk && Pos.wildernessLevel(next) > 0)
				{
					continue;
				}
				if (c + 1 < cost.get(next))
				{
					cost.set(next, c + 1);
					prev.set(next, node);
					via.remove(next);
					heap.push(c + 1, next);
				}
			}
			for (Transport t : transports.from(node))
			{
				if (!t.available(state) || (!wildOk && Pos.wildernessLevel(t.destination) > 0))
				{
					continue;
				}
				int nc = c + Math.max(1, t.duration);
				if (nc < cost.get(t.destination))
				{
					cost.set(t.destination, nc);
					prev.set(t.destination, node);
					via.put(t.destination, t);
					heap.push(nc, t.destination);
				}
			}
		}

		boolean reached = end != Pos.NONE;
		if (!reached)
		{
			// a few tiles short on the same floor is as good as there (the spot is inside a rock or a building)
			end = best;
			reached = bestScore <= NEAR_ENOUGH;
		}
		List<Integer> back = new ArrayList<>();
		for (int n = end; n != Pos.NONE; n = prev.get(n))
		{
			back.add(n);
			if (n == start)
			{
				break;
			}
		}
		int[] tiles = new int[back.size()];
		Map<Integer, Transport> hops = new HashMap<>();
		for (int i = 0; i < tiles.length; i++)
		{
			tiles[i] = back.get(tiles.length - 1 - i);
			Transport t = i == 0 ? null : via.get(tiles[i]);
			if (t != null)
			{
				hops.put(i, t);
			}
		}
		return new Route(tiles, hops, cost.get(end), reached);
	}

	/** How far a tile is from where we want to be, counting a different floor as a long way. */
	private static long score(int node, int target)
	{
		return Pos.distance(node, target) + (Pos.plane(node) == Pos.plane(target) ? 0 : 1000L);
	}

	/** The tile itself if you can stand on it, otherwise the nearest tiles round it that you can. */
	List<Integer> standable(int target)
	{
		List<Integer> out = new ArrayList<>();
		if (!map.isBlocked(target))
		{
			out.add(target);
			return out;
		}
		int x = Pos.x(target);
		int y = Pos.y(target);
		int z = Pos.plane(target);
		for (int r = 1; r <= SNAP_RADIUS && out.isEmpty(); r++)
		{
			for (int dx = -r; dx <= r; dx++)
			{
				for (int dy = -r; dy <= r; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) == r && !map.isBlocked(x + dx, y + dy, z))
					{
						out.add(Pos.pack(x + dx, y + dy, z));
					}
				}
			}
		}
		if (out.isEmpty())
		{
			out.add(target);
		}
		return out;
	}

	/** A value per tile, kept in 64x64 blocks that are only made when a tile in them is written. */
	private static final class Grid
	{
		private final Map<Integer, int[]> pages = new HashMap<>();
		private final int empty;
		private int lastKey = Integer.MIN_VALUE;
		private int[] lastPage;

		Grid(int empty)
		{
			this.empty = empty;
		}

		private static int key(int p)
		{
			return (Pos.x(p) >> 6) | ((Pos.y(p) >> 6) << 9) | (Pos.plane(p) << 18);
		}

		private static int index(int p)
		{
			return (Pos.x(p) & 63) | ((Pos.y(p) & 63) << 6);
		}

		int get(int p)
		{
			int k = key(p);
			int[] page = k == lastKey ? lastPage : pages.get(k);
			if (page == null)
			{
				return empty;
			}
			lastKey = k;
			lastPage = page;
			return page[index(p)];
		}

		void set(int p, int v)
		{
			int k = key(p);
			int[] page = k == lastKey ? lastPage : pages.get(k);
			if (page == null)
			{
				page = new int[4096];
				if (empty != 0)
				{
					Arrays.fill(page, empty);
				}
				pages.put(k, page);
			}
			lastKey = k;
			lastPage = page;
			page[index(p)] = v;
		}
	}

	/** A min-heap of (cost, tile) pairs packed into longs. */
	private static final class Heap
	{
		private long[] a = new long[1 << 14];
		private int n;

		boolean isEmpty()
		{
			return n == 0;
		}

		void push(int cost, int node)
		{
			if (n == a.length)
			{
				a = Arrays.copyOf(a, n * 2);
			}
			long v = ((long) cost << 32) | (node & 0xFFFFFFFFL);
			int i = n++;
			while (i > 0)
			{
				int parent = (i - 1) >> 1;
				if (a[parent] <= v)
				{
					break;
				}
				a[i] = a[parent];
				i = parent;
			}
			a[i] = v;
		}

		long pop()
		{
			long top = a[0];
			long last = a[--n];
			int i = 0;
			while (true)
			{
				int child = 2 * i + 1;
				if (child >= n)
				{
					break;
				}
				if (child + 1 < n && a[child + 1] < a[child])
				{
					child++;
				}
				if (a[child] >= last)
				{
					break;
				}
				a[i] = a[child];
				i = child;
			}
			a[i] = last;
			return top;
		}
	}
}

package com.moneymaker.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** Named places you can ask for a route to, loaded from the places files: kind|name|x y plane;x y plane|note */
public final class Places
{
	/** Somewhere to go. With more than one tile (all the banks, say) the route goes to the nearest. */
	public static final class Place
	{
		private final String kind;
		private final String name;
		private final List<Integer> tiles;
		private final String note;

		public Place(String kind, String name, List<Integer> tiles, String note)
		{
			this.kind = kind;
			this.name = name;
			this.tiles = tiles;
			this.note = note;
		}

		/** "quest", "place", "boss" or "farm". */
		public String getKind()
		{
			return kind;
		}

		public String getName()
		{
			return name;
		}

		/** Tiles packed with {@link Pos}. */
		public List<Integer> getTiles()
		{
			return tiles;
		}

		/** Something worth knowing ("the entrance, the boss is inside"). May be empty. */
		public String getNote()
		{
			return note;
		}
	}

	private final List<Place> all = new ArrayList<>();
	private final Map<String, Place> byKey = new HashMap<>();

	public static Places empty()
	{
		return new Places();
	}

	/** Add the places in a file to this list. Lines that don't parse are skipped. */
	public Places add(InputStream in) throws IOException
	{
		BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
		String line;
		while ((line = r.readLine()) != null)
		{
			line = line.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] f = line.split("\\|", -1);
			if (f.length < 3)
			{
				continue;
			}
			List<Integer> tiles = new ArrayList<>();
			for (String p : f[2].split(";"))
			{
				int tile = Pos.parse(p);
				if (tile != Pos.NONE)
				{
					tiles.add(tile);
				}
			}
			if (tiles.isEmpty() || f[1].trim().isEmpty())
			{
				continue;
			}
			Place place = new Place(f[0].trim().toLowerCase(Locale.ROOT), f[1].trim(),
				Collections.unmodifiableList(tiles), f.length > 3 ? f[3].trim() : "");
			all.add(place);
			byKey.put(key(place.kind, place.name), place);
		}
		return this;
	}

	private static String key(String kind, String name)
	{
		return kind + "|" + name.trim().toLowerCase(Locale.ROOT);
	}

	/** The place of this kind with this name, or null. */
	public Place find(String kind, String name)
	{
		return byKey.get(key(kind, name));
	}

	public List<Place> all()
	{
		return Collections.unmodifiableList(all);
	}

	/** Places of a kind whose name contains the text, names that start with it first. */
	public List<Place> search(String kind, String text, int max)
	{
		String q = text.trim().toLowerCase(Locale.ROOT);
		List<Place> starts = new ArrayList<>();
		List<Place> contains = new ArrayList<>();
		for (Place p : all)
		{
			if (kind != null && !kind.equals(p.kind))
			{
				continue;
			}
			String n = p.name.toLowerCase(Locale.ROOT);
			if (n.startsWith(q))
			{
				starts.add(p);
			}
			else if (n.contains(q))
			{
				contains.add(p);
			}
		}
		starts.addAll(contains);
		return starts.size() > max ? new ArrayList<>(starts.subList(0, max)) : starts;
	}
}

package com.moneymaker.route;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** What your character can use right now: levels, finished quests, what you're carrying. */
public final class PlayerState
{
	/** Which teleports the route may use. */
	public enum Teleports
	{
		NONE("None"),
		FREE("Only free ones"),
		ALL("Any I can use now");

		private final String label;

		Teleports(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Skill name as the game shows it ("Agility") to your level. */
	public final Map<String, Integer> levels = new HashMap<>();
	public int totalLevel;
	public int combatLevel;
	/** Names of the quests you've finished. */
	public final Set<String> questsDone = new HashSet<>();
	/** Item id to how many you have in your inventory and worn equipment. */
	public final Map<Integer, Integer> carried = new HashMap<>();
	public final Set<Integer> worn = new HashSet<>();
	public final Map<Integer, Integer> varbits = new HashMap<>();
	public final Map<Integer, Integer> varps = new HashMap<>();
	/** True once the elite Lumbridge diary is done, when fairy rings no longer need a staff. */
	public boolean fairyRingsWithoutStaff;
	public long nowMinutes = System.currentTimeMillis() / 60_000L;
	public Teleports teleports = Teleports.ALL;
	public boolean avoidWilderness = true;

	/** Someone who can use everything: for tests and for checking the data. */
	public static PlayerState maxed()
	{
		PlayerState s = new PlayerState();
		s.everything = true;
		s.avoidWilderness = false;
		return s;
	}

	/** When true every requirement counts as met. */
	boolean everything;

	Map<Integer, Integer> carried()
	{
		return Collections.unmodifiableMap(carried);
	}
}

package com.moneymaker.route;

/** A world tile packed into one int: x in the low 15 bits, then y, then the plane. */
public final class Pos
{
	public static final int NONE = -1;

	private Pos()
	{
	}

	public static int pack(int x, int y, int plane)
	{
		return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 3) << 30);
	}

	public static int x(int p)
	{
		return p & 0x7FFF;
	}

	public static int y(int p)
	{
		return (p >> 15) & 0x7FFF;
	}

	public static int plane(int p)
	{
		return (p >> 30) & 3;
	}

	/** Tiles apart, ignoring the plane (a diagonal step counts as one). */
	public static int distance(int a, int b)
	{
		return Math.max(Math.abs(x(a) - x(b)), Math.abs(y(a) - y(b)));
	}

	/** "x y plane" as written in the data files, or NONE if it isn't three numbers. */
	public static int parse(String s)
	{
		String[] f = s.trim().split("[ ,]+");
		if (f.length != 3)
		{
			return NONE;
		}
		try
		{
			return pack(Integer.parseInt(f[0]), Integer.parseInt(f[1]), Integer.parseInt(f[2]));
		}
		catch (NumberFormatException e)
		{
			return NONE;
		}
	}

	/** Wilderness level of a tile, or 0 outside the Wilderness. */
	public static int wildernessLevel(int p)
	{
		int x = x(p);
		int y = y(p);
		if (x >= 2944 && x < 3392 && y >= 3525 && y < 3968)
		{
			return (y - 3520) / 8 + 1;
		}
		// the Wilderness caves sit 6400 tiles north of the surface above them
		if (x >= 2944 && x < 3392 && y >= 9920 && y < 10368)
		{
			return (y - 9920) / 8 + 1;
		}
		return 0;
	}

	public static String toString(int p)
	{
		return x(p) + " " + y(p) + " " + plane(p);
	}
}

package com.moneymaker.route;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/** A worked-out route: every tile from where you are to where you're going. */
public final class Route
{
	/** One instruction for the side panel: "Varrock Teleport", "Walk 120 tiles". */
	public static final class Step
	{
		private final String text;
		private final boolean transport;

		Step(String text, boolean transport)
		{
			this.text = text;
			this.transport = transport;
		}

		public String getText()
		{
			return text;
		}

		/** False for plain walking. */
		public boolean isTransport()
		{
			return transport;
		}
	}

	/** A doorway or dungeon entrance this short isn't worth its own line in the list. */
	private static final int MINOR_HOP = 12;

	private final int[] tiles;
	/** Index into tiles to the transport taken to arrive at that tile. */
	private final Map<Integer, Transport> hops;
	private final int cost;
	private final boolean reached;
	private final List<Step> steps;

	Route(int[] tiles, Map<Integer, Transport> hops, int cost, boolean reached)
	{
		this.tiles = tiles;
		this.hops = hops;
		this.cost = cost;
		this.reached = reached;
		this.steps = Collections.unmodifiableList(buildSteps());
	}

	/** Every tile in order, packed with {@link Pos}. The first is where you started. */
	public int[] getTiles()
	{
		return tiles;
	}

	/** The transport used to get to tiles[index], or null if you walk there. */
	public Transport hopInto(int index)
	{
		return hops.get(index);
	}

	/** Rough length: one per tile walked plus the game ticks each transport takes. */
	public int getCost()
	{
		return cost;
	}

	/** False when the place can't be reached and this only gets you as near as possible. */
	public boolean isReached()
	{
		return reached;
	}

	public int getEnd()
	{
		return tiles[tiles.length - 1];
	}

	public List<Step> getSteps()
	{
		return steps;
	}

	public int walkedTiles()
	{
		return tiles.length - 1 - hops.size();
	}

	private List<Step> buildSteps()
	{
		List<Step> out = new ArrayList<>();
		int walked = 0;
		for (int i = 1; i < tiles.length; i++)
		{
			Transport t = hops.get(i);
			if (t == null)
			{
				walked++;
				continue;
			}
			boolean minor = (t.kind == Transport.Kind.OBJECT || t.kind == Transport.Kind.AGILITY)
				&& Pos.distance(tiles[i - 1], tiles[i]) < MINOR_HOP;
			if (minor)
			{
				// doors, stiles and stairs: part of the walk
				walked++;
				continue;
			}
			if (walked > 0)
			{
				out.add(new Step("Walk " + walked + " tile" + (walked == 1 ? "" : "s"), false));
				walked = 0;
			}
			out.add(new Step(t.label(), true));
		}
		if (walked > 0)
		{
			out.add(new Step("Walk " + walked + " tile" + (walked == 1 ? "" : "s"), false));
		}
		return out;
	}
}

package com.moneymaker.route;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

/** Draws the route: a line across the world map, the minimap and the ground in front of you. */
public final class RouteOverlays
{
	/** Only this much of the route ahead of you is drawn in the game view and on the minimap. */
	private static final int AHEAD = 120;
	private static final Stroke LINE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke MAP_LINE = new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke MAP_HOP = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, new float[]{6f, 5f}, 0f);

	private RouteOverlays()
	{
	}

	/** The tile to draw at, in the scene you're in (instances are copies, so the tile is looked up there). */
	private static LocalPoint local(WorldView view, int tile)
	{
		WorldPoint wp = new WorldPoint(Pos.x(tile), Pos.y(tile), Pos.plane(tile));
		if (view.isInstance())
		{
			Collection<WorldPoint> copies = WorldPoint.toLocalInstance(view, wp);
			if (copies.isEmpty())
			{
				return null;
			}
			wp = copies.iterator().next();
		}
		return LocalPoint.fromWorld(view, wp);
	}

	/** The line on the ground, with a marked tile wherever you use a door, boat or teleport. */
	public static final class Scene extends Overlay
	{
		private final Client client;
		private final RouteService routes;
		private final Supplier<Color> color;

		public Scene(Client client, RouteService routes, Supplier<Color> color)
		{
			this.client = client;
			this.routes = routes;
			this.color = color;
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_SCENE);
		}

		@Override
		public Dimension render(Graphics2D g)
		{
			Route route = routes.getRoute();
			WorldView view = client.getTopLevelWorldView();
			if (route == null || view == null)
			{
				return null;
			}
			int[] tiles = route.getTiles();
			int plane = view.getPlane();
			int from = Math.max(0, routes.getProgress());
			int to = Math.min(tiles.length - 1, from + AHEAD);
			Color c = color.get();
			if (c == null)
			{
				// turned off in the settings
				return null;
			}
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(LINE);
			Point prev = null;
			for (int i = from; i <= to; i++)
			{
				int tile = tiles[i];
				LocalPoint lp = Pos.plane(tile) == plane ? local(view, tile) : null;
				Point at = lp == null ? null : Perspective.localToCanvas(client, lp, plane);
				if (at != null && prev != null && route.hopInto(i) == null)
				{
					g.setColor(c);
					g.drawLine(prev.getX(), prev.getY(), at.getX(), at.getY());
				}
				prev = at;
				boolean last = i == tiles.length - 1;
				Transport next = last ? null : route.hopInto(i + 1);
				if (lp != null && (next != null || last))
				{
					Polygon poly = Perspective.getCanvasTilePoly(client, lp);
					if (poly != null)
					{
						g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 60));
						g.fill(poly);
						g.setColor(c);
						g.draw(poly);
					}
					String text = last ? (route.isReached() ? routes.getName() : null) : next.label();
					if (at != null && text != null)
					{
						label(g, text, at.getX(), at.getY() - 18);
					}
				}
			}
			return null;
		}

		private static void label(Graphics2D g, String text, int cx, int y)
		{
			FontMetrics fm = g.getFontMetrics();
			int x = cx - fm.stringWidth(text) / 2;
			g.setColor(Color.BLACK);
			g.drawString(text, x + 1, y + 1);
			g.setColor(Color.WHITE);
			g.drawString(text, x, y);
		}
	}

	/** The same line on the minimap. */
	public static final class Minimap extends Overlay
	{
		private final Client client;
		private final RouteService routes;
		private final Supplier<Color> color;

		public Minimap(Client client, RouteService routes, Supplier<Color> color)
		{
			this.client = client;
			this.routes = routes;
			this.color = color;
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_WIDGETS);
		}

		@Override
		public Dimension render(Graphics2D g)
		{
			Route route = routes.getRoute();
			WorldView view = client.getTopLevelWorldView();
			if (route == null || view == null)
			{
				return null;
			}
			int[] tiles = route.getTiles();
			int plane = view.getPlane();
			int from = Math.max(0, routes.getProgress());
			int to = Math.min(tiles.length - 1, from + AHEAD);
			Color c = color.get();
			if (c == null)
			{
				return null;
			}
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(LINE);
			g.setColor(c);
			Point prev = null;
			for (int i = from; i <= to; i++)
			{
				int tile = tiles[i];
				LocalPoint lp = Pos.plane(tile) == plane ? local(view, tile) : null;
				Point at = lp == null ? null : Perspective.localToMinimap(client, lp);
				if (at != null && prev != null && route.hopInto(i) == null)
				{
					g.drawLine(prev.getX(), prev.getY(), at.getX(), at.getY());
				}
				prev = at;
			}
			return null;
		}
	}

	/** The whole route on the world map: solid where you walk, dashed where something carries you. */
	public static final class WorldMap extends Overlay
	{
		private final Client client;
		private final RouteService routes;
		private final WorldMapOverlay mapOverlay;
		private final Supplier<Color> color;

		public WorldMap(Client client, RouteService routes, WorldMapOverlay mapOverlay, Supplier<Color> color)
		{
			this.client = client;
			this.routes = routes;
			this.mapOverlay = mapOverlay;
			this.color = color;
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.MANUAL);
			drawAfterInterface(InterfaceID.WORLDMAP);
		}

		@Override
		public Dimension render(Graphics2D g)
		{
			Route route = routes.getRoute();
			Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
			if (route == null || map == null || map.isHidden())
			{
				return null;
			}
			Rectangle bounds = map.getBounds();
			Shape oldClip = g.getClip();
			g.setClip(bounds);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Color c = color.get();
			int[] tiles = route.getTiles();
			Point prev = null;
			for (int i = Math.max(0, routes.getProgress()); i < tiles.length; i++)
			{
				int tile = tiles[i];
				Transport hop = route.hopInto(i);
				boolean ends = hop != null || i == tiles.length - 1 || route.hopInto(i + 1) != null;
				// every third tile is plenty for a line on the map, as long as the corners at each hop are kept
				if (!ends && i % 3 != 0)
				{
					continue;
				}
				Point at = mapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(Pos.x(tile), Pos.y(tile), Pos.plane(tile)));
				if (at != null && prev != null)
				{
					g.setColor(hop == null ? c : Color.WHITE);
					g.setStroke(hop == null ? MAP_LINE : MAP_HOP);
					g.drawLine(prev.getX(), prev.getY(), at.getX(), at.getY());
				}
				prev = at;
			}
			g.setClip(oldClip);
			return null;
		}
	}

	/** A small flag for the destination's marker on the world map. */
	public static BufferedImage flag(Color color)
	{
		BufferedImage img = new BufferedImage(15, 18, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Color.BLACK);
		g.fillRect(2, 1, 3, 17);
		g.setColor(Color.WHITE);
		g.fillRect(3, 2, 1, 15);
		Polygon cloth = new Polygon(new int[]{5, 14, 5}, new int[]{2, 6, 10}, 3);
		g.setColor(color);
		g.fill(cloth);
		g.setColor(Color.BLACK);
		g.draw(cloth);
		g.dispose();
		return img;
	}
}

package com.moneymaker.route;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Keeps the route you've asked for: works it out on its own thread, follows you along it, and
 * works it out again if you wander off or teleport somewhere else.
 */
public final class RouteService
{
	private static final Logger log = LoggerFactory.getLogger(RouteService.class);

	/** The route settings, read each time a route is worked out. */
	public interface Settings
	{
		PlayerState.Teleports teleports();

		boolean avoidWilderness();
	}

	/** This close to the end counts as there. */
	private static final int ARRIVE_TILES = 2;
	/** Further than this from every nearby tile of the route and it's worked out again. */
	private static final int OFF_ROUTE_TILES = 7;
	/** Game ticks to leave between working the route out again. */
	private static final int RECALC_TICKS = 4;

	private final Client client;
	private final ClientThread clientThread;
	private final Settings settings;
	private final Runnable onChange;
	private final Class<?> resourceBase;
	private ExecutorService worker;

	private volatile Pathfinder pathfinder;
	private volatile TransportData data = TransportData.empty();
	private volatile boolean loadFailed;

	/** Where you're going, or null when there's no route. */
	private volatile String name;
	private volatile String tag;
	private volatile List<Integer> targets = Collections.emptyList();
	private volatile Route route;
	private volatile int progress;
	private volatile String status;
	private volatile boolean computing;
	/** Goes up every time the destination changes, so an old answer is thrown away. */
	private volatile int generation;
	private int ticksSinceCalc;
	private volatile boolean waitingForLogin;

	public RouteService(Client client, ClientThread clientThread, Settings settings, Runnable onChange, Class<?> resourceBase)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.settings = settings;
		this.onChange = onChange;
		this.resourceBase = resourceBase;
	}

	public void startUp()
	{
		worker = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "adventurers-ledger-route");
			t.setDaemon(true);
			return t;
		});
	}

	public void shutDown()
	{
		clear();
		if (worker != null)
		{
			worker.shutdownNow();
			worker = null;
		}
		pathfinder = null;
		data = TransportData.empty();
	}

	// ---------------------------------------------------------------- asking for a route

	/** Start a route to the nearest of these tiles. Safe to call from any thread. */
	public void routeTo(String name, String tag, List<Integer> tiles)
	{
		if (tiles == null || tiles.isEmpty())
		{
			return;
		}
		generation++;
		this.name = name;
		this.tag = tag;
		this.targets = Collections.unmodifiableList(new ArrayList<>(tiles));
		this.route = null;
		this.progress = 0;
		this.status = "Working out the route...";
		onChange.run();
		clientThread.invokeLater(this::calculate);
	}

	public void routeTo(String name, String tag, WorldPoint point)
	{
		routeTo(name, tag, Collections.singletonList(Pos.pack(point.getX(), point.getY(), point.getPlane())));
	}

	/**
	 * Start a route to where a quest begins. The game's own quest list says where that is; the
	 * list that ships with the plugin is only used if the game doesn't.
	 */
	public void routeToQuest(String questName, Places fallback)
	{
		clientThread.invokeLater(() ->
		{
			WorldPoint p = questStart(questName);
			if (p != null)
			{
				routeTo(questName, "quest", p);
				return;
			}
			Places.Place place = fallback == null ? null : fallback.find("quest", questName);
			if (place != null)
			{
				routeTo(questName, "quest", place.getTiles());
				return;
			}
			generation++;
			name = questName;
			tag = "quest";
			targets = Collections.emptyList();
			route = null;
			status = client.getGameState() == GameState.LOGGED_IN
				? "The game doesn't say where this one starts." : "Log in to find where this quest starts.";
			onChange.run();
		});
	}

	/** Where the game says a quest starts, or null. Client thread only. */
	private WorldPoint questStart(String questName)
	{
		try
		{
			for (Quest q : Quest.values())
			{
				if (!q.getName().equals(questName))
				{
					continue;
				}
				Object[] field = client.getDBTableField(q.getId(), DBTableID.Quest.COL_STARTCOORD, 0);
				if (field != null && field.length > 0 && field[0] instanceof Integer)
				{
					WorldPoint p = WorldPoint.fromCoord((Integer) field[0]);
					if (p.getX() > 0 && p.getY() > 0)
					{
						return p;
					}
				}
				return null;
			}
		}
		catch (RuntimeException e)
		{
			log.debug("No start point from the game for {}", questName, e);
		}
		return null;
	}

	/** Forget the route. */
	public void clear()
	{
		generation++;
		name = null;
		tag = null;
		targets = Collections.emptyList();
		route = null;
		progress = 0;
		status = null;
		computing = false;
		onChange.run();
	}

	// ---------------------------------------------------------------- working it out

	/** Client thread: note what your character can use, then hand the search to the worker. */
	private void calculate()
	{
		List<Integer> want = targets;
		if (want.isEmpty() || computing || worker == null)
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			status = "Log in and the route will appear.";
			waitingForLogin = true;
			onChange.run();
			return;
		}
		if (pathfinder == null)
		{
			if (loadFailed)
			{
				status = "The map data couldn't be loaded.";
				onChange.run();
				return;
			}
			// first route of the session: read the map, then come back here
			computing = true;
			submit(() ->
			{
				load();
				computing = false;
				clientThread.invokeLater(this::calculate);
			});
			return;
		}
		int start = here();
		PlayerState state = snapshot();
		int gen = generation;
		computing = true;
		ticksSinceCalc = 0;
		submit(() ->
		{
			Route found = null;
			try
			{
				found = pathfinder.find(start, want, state);
			}
			catch (RuntimeException e)
			{
				log.warn("Adventurer's Ledger couldn't work out a route", e);
			}
			finally
			{
				computing = false;
			}
			if (gen != generation)
			{
				return;
			}
			route = found;
			progress = 0;
			if (found == null)
			{
				status = "No route found.";
			}
			else if (!found.isReached())
			{
				status = "Can't get all the way there with what you have. This is as close as you can walk.";
			}
			else
			{
				status = null;
			}
			onChange.run();
		});
	}

	private void submit(Runnable job)
	{
		try
		{
			worker.execute(job);
		}
		catch (RejectedExecutionException | NullPointerException e)
		{
			// the plugin was turned off while this was queued
			computing = false;
		}
	}

	private void load()
	{
		try
		{
			CollisionMap map;
			try (InputStream in = open("collision-map.zip"))
			{
				if (in == null)
				{
					throw new IOException("Missing collision-map.zip");
				}
				map = CollisionMap.load(in);
			}
			TransportData td = TransportData.load(this::open);
			data = td;
			pathfinder = new Pathfinder(map, td);
		}
		catch (IOException | RuntimeException e)
		{
			log.error("Adventurer's Ledger couldn't load its map data", e);
			loadFailed = true;
		}
	}

	private InputStream open(String file)
	{
		return resourceBase.getResourceAsStream(file);
	}

	/** Your tile, packed. In an instance (a house, a raid) this is the tile the instance was copied from. */
	private int here()
	{
		Player p = client.getLocalPlayer();
		WorldPoint w = client.getTopLevelWorldView().isInstance()
			? WorldPoint.fromLocalInstance(client, p.getLocalLocation()) : p.getWorldLocation();
		if (w == null)
		{
			w = p.getWorldLocation();
		}
		return Pos.pack(w.getX(), w.getY(), w.getPlane());
	}

	/** Client thread: read everything a transport might ask about. */
	private PlayerState snapshot()
	{
		PlayerState s = new PlayerState();
		s.teleports = settings.teleports();
		s.avoidWilderness = settings.avoidWilderness();
		for (Skill skill : Skill.values())
		{
			s.levels.put(skill.getName(), client.getRealSkillLevel(skill));
		}
		s.totalLevel = client.getTotalLevel();
		Player me = client.getLocalPlayer();
		s.combatLevel = me == null ? 3 : me.getCombatLevel();

		TransportData td = data;
		if (!td.questNames().isEmpty())
		{
			for (Quest q : Quest.values())
			{
				if (td.questNames().contains(q.getName()) && q.getState(client) == QuestState.FINISHED)
				{
					s.questsDone.add(q.getName());
				}
			}
		}
		for (int id : td.varbitIds())
		{
			s.varbits.put(id, client.getVarbitValue(id));
		}
		for (int id : td.varpIds())
		{
			s.varps.put(id, client.getVarpValue(id));
		}
		s.fairyRingsWithoutStaff = client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1;

		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			for (Item it : worn.getItems())
			{
				if (it.getId() > 0 && it.getQuantity() > 0)
				{
					s.worn.add(it.getId());
					s.carried.merge(it.getId(), it.getQuantity(), Integer::sum);
				}
			}
		}
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv != null)
		{
			for (Item it : inv.getItems())
			{
				if (it.getId() > 0 && it.getQuantity() > 0)
				{
					s.carried.merge(it.getId(), it.getQuantity(), Integer::sum);
				}
			}
		}
		return s;
	}

	// ---------------------------------------------------------------- following you

	/** Call once a game tick, on the client thread. */
	public void onGameTick()
	{
		if (targets.isEmpty() || client.getLocalPlayer() == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticksSinceCalc++;
		Route r = route;
		if (r == null)
		{
			// asked for while logged out: work it out now you're in
			if (waitingForLogin && !computing)
			{
				waitingForLogin = false;
				calculate();
			}
			return;
		}
		int me = here();
		int[] tiles = r.getTiles();
		int end = r.getEnd();
		if (r.isReached() && Pos.plane(me) == Pos.plane(end) && Pos.distance(me, end) <= ARRIVE_TILES)
		{
			String arrived = name;
			clear();
			status = "You've arrived" + (arrived == null ? "." : ": " + arrived + ".");
			onChange.run();
			return;
		}
		// where on the route are you? look a little behind and a good way ahead
		int from = Math.max(0, progress - 5);
		int to = Math.min(tiles.length - 1, progress + 80);
		int nearest = -1;
		int nearestDist = Integer.MAX_VALUE;
		for (int i = from; i <= to; i++)
		{
			if (Pos.plane(tiles[i]) != Pos.plane(me))
			{
				continue;
			}
			int d = Pos.distance(tiles[i], me);
			if (d < nearestDist || (d == nearestDist && i > nearest && d <= 1))
			{
				nearestDist = d;
				nearest = i;
			}
		}
		if (nearest >= 0 && nearestDist <= OFF_ROUTE_TILES)
		{
			if (nearestDist <= 2)
			{
				// the overlays read this each frame; nothing else needs telling
				progress = nearest;
			}
			return;
		}
		if (!computing && ticksSinceCalc >= RECALC_TICKS)
		{
			calculate();
		}
	}

	// ---------------------------------------------------------------- for the overlays and the panel

	/** The route, or null when there isn't one (yet). */
	public Route getRoute()
	{
		return route;
	}

	/** How far along the route's tiles you are. */
	public int getProgress()
	{
		return progress;
	}

	/** Where the route goes, or null when there's no route. */
	public String getName()
	{
		return name;
	}

	/** What asked for the route ("quest", "farm:herbs"), so it can tell the route is its own. */
	public String getTag()
	{
		return tag;
	}

	/** A line to show the player ("Working out the route..."), or null. */
	public String getStatus()
	{
		return status;
	}

	public boolean isActive()
	{
		return name != null;
	}

	/** The tile the route ends at (or will), or null. */
	public WorldPoint getDestination()
	{
		Route r = route;
		int p;
		if (r != null)
		{
			p = r.getEnd();
		}
		else if (!targets.isEmpty())
		{
			p = targets.get(0);
		}
		else
		{
			return null;
		}
		return new WorldPoint(Pos.x(p), Pos.y(p), Pos.plane(p));
	}
}

package com.moneymaker.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Where to go for each training method, from trainspots.txt:
 * method name|x y plane;x y plane|where. "BANK" in place of tiles means the nearest bank.
 */
public final class TrainSpots
{
	/** Name of the "Nearest bank" place in places.txt, used for BANK lines. */
	static final String BANK_PLACE = "Nearest bank";

	private final Map<String, Places.Place> byMethod = new HashMap<>();

	public static TrainSpots empty()
	{
		return new TrainSpots();
	}

	/**
	 * Read trainspots.txt. {@code places} supplies the bank tiles for BANK lines; lines that
	 * don't parse are skipped.
	 */
	public static TrainSpots load(InputStream in, Places places) throws IOException
	{
		TrainSpots spots = new TrainSpots();
		Places.Place bank = places == null ? null : places.find("place", BANK_PLACE);
		BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
		String line;
		while ((line = r.readLine()) != null)
		{
			line = line.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] f = line.split("\\|", -1);
			if (f.length < 3 || f[0].trim().isEmpty())
			{
				continue;
			}
			String method = f[0].trim();
			String where = f[2].trim();
			List<Integer> tiles = new ArrayList<>();
			if ("BANK".equalsIgnoreCase(f[1].trim()))
			{
				if (bank == null)
				{
					continue;
				}
				tiles.addAll(bank.getTiles());
			}
			else
			{
				for (String p : f[1].split(";"))
				{
					int tile = Pos.parse(p);
					if (tile != Pos.NONE)
					{
						tiles.add(tile);
					}
				}
			}
			if (tiles.isEmpty())
			{
				continue;
			}
			spots.byMethod.put(method, new Places.Place("train", where.isEmpty() ? method : where,
				Collections.unmodifiableList(tiles), ""));
		}
		return spots;
	}

	/** Where to go for this training method, or null if it has no single place. */
	public Places.Place find(String methodName)
	{
		return methodName == null ? null : byMethod.get(methodName);
	}

	/** Every method name with a place, for checks. */
	public Map<String, Places.Place> all()
	{
		return Collections.unmodifiableMap(byMethod);
	}
}

package com.moneymaker.route;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** One way of getting from a tile to another that isn't walking: a door, a boat, a teleport. */
public final class Transport
{
	/** The kinds of transport, one per data file. */
	public enum Kind
	{
		OBJECT("transports", null, false, 0),
		AGILITY("agility_shortcuts", null, false, 0),
		BOAT("boats", "Boat", false, 0),
		CANOE("canoes", "Canoe", false, 0),
		CHARTER_SHIP("charter_ships", "Charter ship", false, 0),
		SHIP("ships", "Ship", false, 0),
		FAIRY_RING("fairy_rings", "Fairy ring", false, 6),
		GNOME_GLIDER("gnome_gliders", "Gnome glider", false, 6),
		BALLOON("hot_air_balloons", "Hot air balloon", false, 7),
		MAGIC_CARPET("magic_carpets", "Magic carpet", false, 0),
		MUSHTREE("magic_mushtrees", "Magic Mushtree", false, 5),
		MINECART("minecarts", "Minecart", false, 0),
		QUETZAL("quetzals", "Quetzal", false, 5),
		SPIRIT_TREE("spirit_trees", "Spirit tree", false, 5),
		LEVER("teleportation_levers", "Lever", false, 0),
		PORTAL("teleportation_portals", "Portal", false, 0),
		OBELISK("wilderness_obelisks", "Obelisk", false, 0),
		QUETZAL_WHISTLE("quetzal_whistle", null, true, 0),
		ITEM("teleportation_items", null, true, 0),
		MINIGAME("teleportation_minigames", "Minigame teleport", true, 0),
		SPELL("teleportation_spells", null, true, 0),
		HOME("teleportation_spells_home", null, true, 0);

		final String file;
		final String label;
		/** True for things you can use from anywhere rather than at a spot on the map. */
		final boolean teleport;
		/** For networks (fairy rings and the like): don't link two ends closer together than this. */
		final int minDistance;

		Kind(String file, String label, boolean teleport, int minDistance)
		{
			this.file = file;
			this.label = label;
			this.teleport = teleport;
			this.minDistance = minDistance;
		}
	}

	/** At least `qty` of any of `ids`, or one of the staves or off-hands worn (they give endless runes). */
	static final class ItemChoice
	{
		final int[] ids;
		final int[] staves;
		final int[] offhands;
		final int qty;

		ItemChoice(int[] ids, int[] staves, int[] offhands, int qty)
		{
			this.ids = ids;
			this.staves = staves;
			this.offhands = offhands;
			this.qty = qty;
		}

		boolean met(PlayerState s)
		{
			for (int id : staves)
			{
				if (s.worn.contains(id))
				{
					return true;
				}
			}
			for (int id : offhands)
			{
				if (s.worn.contains(id))
				{
					return true;
				}
			}
			long have = 0;
			for (int id : ids)
			{
				Integer n = s.carried.get(id);
				if (n != null)
				{
					have += n;
				}
			}
			return ids.length > 0 && have >= qty;
		}
	}

	/** A game setting (varbit or varplayer) that has to hold a value. */
	static final class VarCheck
	{
		final boolean varbit;
		final int id;
		final char op;
		final int value;

		VarCheck(boolean varbit, int id, char op, int value)
		{
			this.varbit = varbit;
			this.id = id;
			this.op = op;
			this.value = value;
		}

		boolean met(PlayerState s)
		{
			Integer v = (varbit ? s.varbits : s.varps).get(id);
			if (v == null)
			{
				return false;
			}
			switch (op)
			{
				case '=':
					return v == value;
				case '>':
					return v > value;
				case '<':
					return v < value;
				case '&':
					return (v & value) > 0;
				case '@':
					// a cooldown: the setting holds the minute it was last used
					return s.nowMinutes - (long) v > value;
				default:
					return false;
			}
		}
	}

	/** Dramen staff and the Lunar staves: one has to be carried to use fairy rings before the elite Lumbridge diary. */
	private static final int[] FAIRY_STAVES = {772, 9091, 9092, 9093, 9084};

	private static boolean carries(PlayerState s, int[] ids)
	{
		for (int id : ids)
		{
			if (s.carried.containsKey(id))
			{
				return true;
			}
		}
		return false;
	}

	final Kind kind;
	final int origin;
	final int destination;
	/** Game ticks it takes. */
	final int duration;
	final String display;
	final String object;
	final boolean consumable;
	/** Deepest Wilderness level a teleport still works at. */
	final int maxWilderness;
	final List<String> skills;
	final List<String> quests;
	/** Every entry must be met; each entry is a list of alternatives. */
	final List<List<ItemChoice>> items;
	final List<VarCheck> vars;
	/** False when the data asks for something this plugin can't check, so the transport is never used. */
	final boolean usable;

	Transport(Kind kind, int origin, int destination, int duration, String display, String object,
		boolean consumable, int maxWilderness, List<String> skills, List<String> quests,
		List<List<ItemChoice>> items, List<VarCheck> vars, boolean usable)
	{
		this.kind = kind;
		this.origin = origin;
		this.destination = destination;
		this.duration = duration;
		this.display = display;
		this.object = object;
		this.consumable = consumable;
		this.maxWilderness = maxWilderness;
		this.skills = skills;
		this.quests = quests;
		this.items = items;
		this.vars = vars;
		this.usable = usable;
	}

	/** Join the way in to a network (a fairy ring you stand at) with a way out (a ring you can dial). */
	static Transport join(Transport from, Transport to)
	{
		return new Transport(from.kind, from.origin, to.destination, Math.max(from.duration, to.duration),
			to.display != null ? to.display : from.display, from.object, from.consumable || to.consumable,
			Math.max(from.maxWilderness, to.maxWilderness), concat(from.skills, to.skills), concat(from.quests, to.quests),
			concat(from.items, to.items), concat(from.vars, to.vars), from.usable && to.usable);
	}

	private static <T> List<T> concat(List<T> a, List<T> b)
	{
		if (b.isEmpty())
		{
			return a;
		}
		if (a.isEmpty())
		{
			return b;
		}
		List<T> out = new ArrayList<>(a);
		out.addAll(b);
		return Collections.unmodifiableList(out);
	}

	public int getOrigin()
	{
		return origin;
	}

	public int getDestination()
	{
		return destination;
	}

	public Kind getKind()
	{
		return kind;
	}

	public boolean isTeleport()
	{
		return kind.teleport;
	}

	/** Can this character use it right now? */
	boolean available(PlayerState s)
	{
		if (!usable)
		{
			return false;
		}
		if (s.everything)
		{
			return true;
		}
		if (kind.teleport)
		{
			if (s.teleports == PlayerState.Teleports.NONE)
			{
				return false;
			}
			if (s.teleports == PlayerState.Teleports.FREE && (consumable || kind == Kind.SPELL))
			{
				return false;
			}
		}
		if (kind == Kind.FAIRY_RING && !s.fairyRingsWithoutStaff && !carries(s, FAIRY_STAVES))
		{
			return false;
		}
		for (String req : skills)
		{
			int space = req.indexOf(' ');
			if (space < 0)
			{
				return false;
			}
			String name = req.substring(space + 1);
			int need;
			try
			{
				need = "Max".equals(req.substring(0, space)) ? 99 : Integer.parseInt(req.substring(0, space));
			}
			catch (NumberFormatException e)
			{
				return false;
			}
			String lower = name.toLowerCase(java.util.Locale.ROOT);
			int have;
			if (lower.startsWith("total"))
			{
				have = s.totalLevel;
			}
			else if (lower.startsWith("combat"))
			{
				have = s.combatLevel;
			}
			else
			{
				Integer lvl = s.levels.get(name);
				if (lvl == null)
				{
					return false;
				}
				have = lvl;
			}
			if (have < need)
			{
				return false;
			}
		}
		for (String q : quests)
		{
			if (!s.questsDone.contains(q))
			{
				return false;
			}
		}
		for (VarCheck v : vars)
		{
			if (!v.met(s))
			{
				return false;
			}
		}
		for (List<ItemChoice> any : items)
		{
			boolean ok = false;
			for (ItemChoice c : any)
			{
				if (c.met(s))
				{
					ok = true;
					break;
				}
			}
			if (!ok)
			{
				return false;
			}
		}
		return true;
	}

	/** What to tell the player: "Varrock Teleport", "Fairy ring: A I Q", "Climb-down Ladder". */
	public String label()
	{
		String what = object == null ? null : object.replaceAll("\\s+\\d+$", "").trim();
		if (kind.label != null)
		{
			return display != null && !display.isEmpty() ? kind.label + ": " + display.replaceFirst("^\\d+: ", "") : kind.label;
		}
		if (display != null && !display.isEmpty())
		{
			return display;
		}
		return what == null || what.isEmpty() ? "Use the shortcut" : what;
	}
}

package com.moneymaker.route;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Every door, ladder, boat, fairy ring and teleport the route finder knows about, read from the
 * tab-separated files in route/transports. The files come from the Shortest Path plugin
 * (github.com/Skretzo/shortest-path, BSD 2-Clause).
 */
public final class TransportData
{
	/** Transports you use at a spot, by the tile you stand on. */
	private final Map<Integer, List<Transport>> byOrigin;
	/** Teleports: usable from anywhere. */
	private final List<Transport> teleports;
	private final Set<Integer> varbitIds = new HashSet<>();
	private final Set<Integer> varpIds = new HashSet<>();
	private final Set<String> questNames = new HashSet<>();

	/** Opens a data file by name, or returns null if it isn't there. */
	public interface Source
	{
		InputStream open(String name) throws IOException;
	}

	private TransportData(Map<Integer, List<Transport>> byOrigin, List<Transport> teleports)
	{
		this.byOrigin = byOrigin;
		this.teleports = teleports;
		for (List<Transport> list : byOrigin.values())
		{
			list.forEach(this::note);
		}
		teleports.forEach(this::note);
	}

	private void note(Transport t)
	{
		for (Transport.VarCheck v : t.vars)
		{
			(v.varbit ? varbitIds : varpIds).add(v.id);
		}
		questNames.addAll(t.quests);
	}

	public static TransportData empty()
	{
		return new TransportData(Collections.emptyMap(), Collections.emptyList());
	}

	public List<Transport> from(int tile)
	{
		List<Transport> list = byOrigin.get(tile);
		return list == null ? Collections.emptyList() : list;
	}

	public List<Transport> teleports()
	{
		return teleports;
	}

	/** The game settings that have to be read before a route can be worked out. */
	public Set<Integer> varbitIds()
	{
		return varbitIds;
	}

	public Set<Integer> varpIds()
	{
		return varpIds;
	}

	public Set<String> questNames()
	{
		return questNames;
	}

	public int size()
	{
		int n = teleports.size();
		for (List<Transport> list : byOrigin.values())
		{
			n += list.size();
		}
		return n;
	}

	public static TransportData load(Source source) throws IOException
	{
		Map<String, int[][]> variations = new HashMap<>();
		try (InputStream in = source.open("item-variations.tsv"))
		{
			if (in != null)
			{
				loadVariations(in, variations);
			}
		}
		Map<Integer, List<Transport>> byOrigin = new HashMap<>();
		List<Transport> teleports = new ArrayList<>();
		for (Transport.Kind kind : Transport.Kind.values())
		{
			try (InputStream in = source.open("transports/" + kind.file + ".tsv"))
			{
				if (in == null)
				{
					continue;
				}
				loadFile(kind, in, variations, byOrigin, teleports);
			}
		}
		for (Map.Entry<Integer, List<Transport>> e : byOrigin.entrySet())
		{
			e.setValue(Collections.unmodifiableList(e.getValue()));
		}
		return new TransportData(byOrigin, Collections.unmodifiableList(teleports));
	}

	private static void loadVariations(InputStream in, Map<String, int[][]> out) throws IOException
	{
		BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
		String line;
		while ((line = r.readLine()) != null)
		{
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] f = line.split("\t", -1);
			out.put(f[0].trim().toUpperCase(Locale.ROOT), new int[][]{
				ints(f.length > 1 ? f[1] : ""), ints(f.length > 2 ? f[2] : ""), ints(f.length > 3 ? f[3] : "")});
		}
	}

	private static int[] ints(String csv)
	{
		List<Integer> out = new ArrayList<>();
		for (String s : csv.split(","))
		{
			s = s.trim();
			if (!s.isEmpty())
			{
				try
				{
					out.add(Integer.parseInt(s));
				}
				catch (NumberFormatException ignored)
				{
					// skip a bad id rather than lose the whole line
				}
			}
		}
		int[] a = new int[out.size()];
		for (int i = 0; i < a.length; i++)
		{
			a[i] = out.get(i);
		}
		return a;
	}

	private static void loadFile(Transport.Kind kind, InputStream in, Map<String, int[][]> variations,
		Map<Integer, List<Transport>> byOrigin, List<Transport> teleports) throws IOException
	{
		BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
		String line = r.readLine();
		if (line == null || !line.startsWith("#"))
		{
			throw new IOException(kind.file + ".tsv has no header line");
		}
		// the first line names the columns
		Map<String, Integer> col = new HashMap<>();
		String[] head = line.substring(1).split("\t", -1);
		for (int i = 0; i < head.length; i++)
		{
			col.put(head[i].trim().toLowerCase(Locale.ROOT), i);
		}
		boolean hasOrigin = col.containsKey("origin");
		List<Transport> ins = new ArrayList<>();
		List<Transport> outs = new ArrayList<>();
		while ((line = r.readLine()) != null)
		{
			if (line.trim().isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] f = line.split("\t", -1);
			String originText = field(f, col, "origin");
			String destText = field(f, col, "destination");
			int origin = originText.isEmpty() ? Pos.NONE : Pos.parse(originText);
			int dest = destText.isEmpty() ? Pos.NONE : Pos.parse(destText);
			if ((!originText.isEmpty() && origin == Pos.NONE) || (!destText.isEmpty() && dest == Pos.NONE))
			{
				continue;
			}
			boolean[] usable = {true};
			List<String> skills = split(field(f, col, "skills"));
			List<String> quests = split(field(f, col, "quests"));
			List<List<Transport.ItemChoice>> items = items(field(f, col, "items"), variations, usable);
			List<Transport.VarCheck> vars = new ArrayList<>();
			vars(field(f, col, "varbits"), true, vars, usable);
			vars(field(f, col, "varplayers"), false, vars, usable);
			String display = field(f, col, "display info");
			String object = field(f, col, "menuoption menutarget objectid");
			Transport t = new Transport(kind, origin, dest, number(field(f, col, "duration"), 0),
				display.isEmpty() ? null : display, object.isEmpty() ? null : object,
				"T".equalsIgnoreCase(field(f, col, "consumable")), number(field(f, col, "wilderness level"), -1),
				skills, quests, items, vars.isEmpty() ? Collections.emptyList() : Collections.unmodifiableList(vars), usable[0]);
			if (origin != Pos.NONE && dest != Pos.NONE)
			{
				if (origin != dest)
				{
					byOrigin.computeIfAbsent(origin, k -> new ArrayList<>(2)).add(t);
				}
			}
			else if (origin != Pos.NONE)
			{
				ins.add(t);
			}
			else if (dest != Pos.NONE)
			{
				if (hasOrigin)
				{
					outs.add(t);
				}
				else
				{
					teleports.add(t);
				}
			}
		}
		// a network: every way in connects to every way out
		for (Transport from : ins)
		{
			for (Transport to : outs)
			{
				if (Pos.distance(from.origin, to.destination) > kind.minDistance || Pos.plane(from.origin) != Pos.plane(to.destination))
				{
					byOrigin.computeIfAbsent(from.origin, k -> new ArrayList<>(2)).add(Transport.join(from, to));
				}
			}
		}
	}

	private static String field(String[] f, Map<String, Integer> col, String name)
	{
		Integer i = col.get(name);
		return i == null || i >= f.length ? "" : f[i].trim();
	}

	private static int number(String s, int fallback)
	{
		try
		{
			return s.isEmpty() ? fallback : Integer.parseInt(s);
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	private static List<String> split(String s)
	{
		if (s.isEmpty())
		{
			return Collections.emptyList();
		}
		List<String> out = new ArrayList<>();
		for (String part : s.split(";"))
		{
			if (!part.trim().isEmpty())
			{
				out.add(part.trim());
			}
		}
		return Collections.unmodifiableList(out);
	}

	/** "AIR_RUNE=3&&LAW_RUNE=1" or "13121=1||13122=1": every "&" part is needed, "|" parts are alternatives. */
	private static List<List<Transport.ItemChoice>> items(String s, Map<String, int[][]> variations, boolean[] usable)
	{
		if (s.isEmpty())
		{
			return Collections.emptyList();
		}
		String norm = s.replace(" ", "").replace("&&", "&").replace("||", "|").toUpperCase(Locale.ROOT);
		List<List<Transport.ItemChoice>> all = new ArrayList<>();
		for (String and : norm.split("&"))
		{
			List<Transport.ItemChoice> any = new ArrayList<>();
			for (String or : and.split("\\|"))
			{
				String[] kv = or.split("=");
				if (kv.length != 2)
				{
					usable[0] = false;
					continue;
				}
				int qty = number(kv[1], -1);
				if (qty < 0)
				{
					usable[0] = false;
					continue;
				}
				int[] none = new int[0];
				if (kv[0].startsWith("UNLOCK_"))
				{
					// something the game doesn't tell the client (an axe left at a canoe station):
					// count it as not there, the other alternatives still work
					continue;
				}
				int[][] v = variations.get(kv[0]);
				if (v != null)
				{
					any.add(new Transport.ItemChoice(v[0], v[1], v[2], qty));
				}
				else
				{
					int id = number(kv[0], -1);
					if (id < 0)
					{
						usable[0] = false;
						continue;
					}
					any.add(new Transport.ItemChoice(new int[]{id}, none, none, qty));
				}
			}
			all.add(Collections.unmodifiableList(any));
		}
		return Collections.unmodifiableList(all);
	}

	private static void vars(String s, boolean varbit, List<Transport.VarCheck> out, boolean[] usable)
	{
		if (s.isEmpty())
		{
			return;
		}
		for (String part : s.split(";"))
		{
			part = part.trim();
			if (part.isEmpty())
			{
				continue;
			}
			boolean ok = false;
			for (char op : new char[]{'&', '@', '=', '>', '<'})
			{
				int at = part.indexOf(op);
				if (at > 0)
				{
					int id = number(part.substring(0, at), -1);
					String v = part.substring(at + 1);
					if (id >= 0 && v.matches("-?\\d+"))
					{
						out.add(new Transport.VarCheck(varbit, id, op, Integer.parseInt(v)));
						ok = true;
					}
					break;
				}
			}
			if (!ok)
			{
				usable[0] = false;
			}
		}
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerPlugin;
import com.moneymaker.data.BossCheck;
import com.moneymaker.data.BossQuests;
import com.moneymaker.route.Places;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import com.moneymaker.data.BossSetup;
import com.moneymaker.data.Gear;
import com.moneymaker.data.GearPricer;
import com.moneymaker.data.PriceBook;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.QuestState;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.LinkBrowser;

/** Gear for each boss, per slot from starter to best in slot (OSRS Wiki ranking), at live GE prices. */
class BossesPanel extends JPanel
{
	private final MoneyMakerPlugin plugin;
	private final ItemManager itemManager;
	private final JComboBox<BossSetup> setups = new JComboBox<>();
	private final JLabel budget = stat();
	private final JLabel mid = stat();
	private final JLabel best = stat();
	private final JLabel untradeables = UiUtil.label(" ", UiUtil.MUTED, false);
	private final JPanel list = UiUtil.verticalList();
	private final JButton way = new JButton("Show the way there");

	BossesPanel(MoneyMakerPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 4));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (BossSetup s : plugin.getBosses())
		{
			setups.addItem(s);
		}
		setups.setFocusable(false);
		setups.addActionListener(e -> refresh());
		top.add(setups);

		JPanel totals = new JPanel(new GridLayout(1, 3, 4, 0));
		totals.setBackground(ColorScheme.DARK_GRAY_COLOR);
		totals.add(box("Budget", budget));
		totals.add(box("Mid", mid));
		totals.add(box("Best", best));
		top.add(totals);
		top.add(untradeables);

		JButton wiki = new JButton("Open wiki strategy page");
		wiki.setFocusable(false);
		wiki.addActionListener(e ->
		{
			BossSetup s = (BossSetup) setups.getSelectedItem();
			if (s != null)
			{
				LinkBrowser.browse(s.getUrl());
			}
		});
		top.add(wiki);
		way.setFocusable(false);
		way.addActionListener(e ->
		{
			BossSetup s = (BossSetup) setups.getSelectedItem();
			Places.Place p = s == null ? null : plugin.getPlaces().find("boss", s.getBoss());
			if (p != null && plugin.canRoutePerks())
			{
				plugin.routeTo(p, "boss");
			}
		});
		top.add(way);
		top.setBorder(new EmptyBorder(0, 0, 4, 0));

		add(top, BorderLayout.NORTH);
		add(UiUtil.scroll(list), BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		list.removeAll();
		BossSetup setup = (BossSetup) setups.getSelectedItem();
		showWayButton(setup);
		PriceBook prices = plugin.getPrices();
		GearPricer pricer = plugin.getGearPricer();

		if (setup == null)
		{
			list.add(UiUtil.emptyState("No boss data loaded."));
			repaintList();
			return;
		}
		addCheck(setup, !prices.isEmpty());
		addQuests(setup);
		if (prices.isEmpty())
		{
			list.add(UiUtil.emptyState("Fetching prices..."));
			repaintList();
			return;
		}

		Map<String, Gear.Owned> owned = plugin.isLoggedIn() ? plugin.getOwned() : java.util.Collections.emptyMap();
		long budgetTotal = 0;
		long midTotal = 0;
		long bestTotal = 0;
		List<String> unpriced = new ArrayList<>();

		for (BossSetup.Slot slot : setup.getSlots())
		{
			List<List<String>> tiers = slot.getTiers(); // best first
			int n = tiers.size();
			List<GearPricer.Price> priced = new ArrayList<>();
			for (List<String> tier : tiers)
			{
				priced.add(pricer.cheapestOf(tier, prices));
			}

			budgetTotal += cost(priced.get(n - 1));
			midTotal += cost(priced.get(n / 2));
			bestTotal += cost(priced.get(0));
			if (!priced.get(0).isTradeable())
			{
				unpriced.add(priced.get(0).getName());
			}

			list.add(UiUtil.header(slot.getName() + "  (weakest to strongest)"));
			// cheapest (worst) first, up to best in slot
			for (int i = n - 1; i >= 0; i--)
			{
				GearPricer.Price p = priced.get(i);
				List<String> alts = tiers.get(i);
				String title = String.join(" / ", alts);
				String tier = i == 0 ? "Best in slot" : i == n - 1 ? "Starter" : "Upgrade " + (n - 1 - i);
				String value = p.isTradeable() ? UiUtil.compact(p.getCost()) : "—";
				Color color = i == 0 ? UiUtil.PROFIT : p.isTradeable() ? ColorScheme.GRAND_EXCHANGE_PRICE : UiUtil.MUTED;
				String line3 = p.getNote() != null ? p.getNote() : alts.size() > 1 ? "Cheapest of these: " + p.getName() : null;
				Gear.Owned mine = BossCheck.ownedInTier(alts, owned);
				if (mine != null)
				{
					line3 = "You own this (" + mine.getWhere() + ")";
				}

				ItemRow row = new ItemRow(itemManager, p.getIconId(), title, value, color, tier, line3, tooltip(alts, p));
				if (mine != null)
				{
					row.setLine3Color(UiUtil.PROFIT);
				}
				else if (p.isTradeable())
				{
					String wanted = p.getName();
					row.action("Plan how to afford this", () -> plugin.planFor(wanted));
				}
				UiUtil.addRow(list, row);
			}
		}

		budget.setText(UiUtil.compact(budgetTotal));
		mid.setText(UiUtil.compact(midTotal));
		best.setText(UiUtil.compact(bestTotal));
		untradeables.setText(unpriced.isEmpty()
			? "Totals are GE prices for tradeable gear only."
			: "<html>Totals cover tradeable gear only. Best-in-slot also needs: "
				+ String.join(", ", unpriced) + "</html>");
		repaintList();
	}

	/**
	 * "Can you fight it?": your levels and quests against what the boss needs, and how much of
	 * the gear you already own. Needs you to be logged in.
	 */
	private void addCheck(BossSetup setup, boolean withGear)
	{
		List<BossCheck.SkillReq> skills = plugin.getBossCheck().skillsFor(setup.getBoss());
		BossQuests quests = plugin.getBossQuests();

		list.add(UiUtil.header("Can you fight it?"));
		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(5, 6, 5, 6));

		if (!plugin.isLoggedIn())
		{
			StringBuilder sb = new StringBuilder("Log in to check your levels, quests and gear.");
			for (BossCheck.SkillReq r : skills)
			{
				sb.append("<br>Needs ").append(r.getLevel()).append(' ').append(pretty(r.getSkill()));
			}
			box.add(checkLine(sb.toString(), UiUtil.MUTED));
			UiUtil.addRow(list, box);
			return;
		}

		int missing = 0;
		for (BossCheck.SkillReq r : skills)
		{
			long[] have = plugin.getSkill(r.getSkill());
			boolean ok = have != null && have[0] >= r.getLevel();
			missing += ok ? 0 : 1;
			box.add(checkLine((ok ? "&#10003; " : "&#10007; ") + r.getLevel() + " " + pretty(r.getSkill())
				+ " (you: " + (have != null ? have[0] : "?") + ")"
				+ (r.getNote().isEmpty() ? "" : "<br><i>" + esc(r.getNote()) + "</i>"), ok ? UiUtil.PROFIT : UiUtil.LOSS));
		}

		LinkedHashSet<String> todo = new LinkedHashSet<>();
		boolean needsQuests = false;
		for (BossQuests.Req r : quests.forBoss(setup.getBoss()))
		{
			needsQuests = true;
			if (plugin.getQuestState(r.getQuest()) == QuestState.FINISHED)
			{
				continue;
			}
			for (String q : quests.lineFor(r.getQuest()))
			{
				if (plugin.getQuestState(q) != QuestState.FINISHED)
				{
					todo.add(q);
				}
			}
			todo.add(r.getQuest());
		}
		if (needsQuests)
		{
			missing += todo.isEmpty() ? 0 : 1;
			box.add(todo.isEmpty() ? checkLine("&#10003; Quests done", UiUtil.PROFIT)
				: checkLine("&#10007; " + todo.size() + (todo.size() == 1 ? " quest" : " quests") + " to do (listed below)", UiUtil.LOSS));
		}
		if (skills.isEmpty() && !needsQuests)
		{
			box.add(checkLine("&#10003; No level or quest needed", UiUtil.PROFIT));
		}

		if (withGear)
		{
			BossCheck.Kit kit = BossCheck.kit(setup, plugin.getGearPricer(), plugin.getPrices(), plugin.getOwned());
			StringBuilder sb = new StringBuilder("Gear: you own something for <b>").append(kit.getSlotsOwned())
				.append(" of ").append(kit.getSlots()).append("</b> slots");
			if (kit.getCostToFill() > 0)
			{
				sb.append("<br>About <b>").append(UiUtil.compact(kit.getCostToFill()))
					.append("</b> to fill the rest with the cheapest options");
			}
			if (!kit.getToEarn().isEmpty())
			{
				sb.append("<br>Can't be bought: ").append(esc(String.join(", ", kit.getToEarn())));
			}
			if (!plugin.isBankSeen())
			{
				sb.append("<br><i>Open your bank once so it's counted.</i>");
			}
			box.add(checkLine(sb.toString(), Color.WHITE));
		}

		JLabel verdict = UiUtil.label(missing == 0 ? "Yes, you meet the requirements" : "Not yet", missing == 0 ? UiUtil.PROFIT : IN_PROGRESS, true);
		verdict.setAlignmentX(LEFT_ALIGNMENT);
		verdict.setBorder(new EmptyBorder(0, 0, 3, 0));
		box.add(verdict, 0);
		UiUtil.addRow(list, box);
	}

	private static JLabel checkLine(String html, Color color)
	{
		JLabel l = UiUtil.label("<html><div style='width:" + QUEST_TEXT_WIDTH + "px'>" + html + "</div></html>", color, false);
		l.setAlignmentX(LEFT_ALIGNMENT);
		l.setBorder(new EmptyBorder(1, 0, 1, 0));
		return l;
	}

	private static String pretty(String skill)
	{
		return skill.isEmpty() ? skill : skill.charAt(0) + skill.substring(1).toLowerCase(Locale.ROOT);
	}

	/** Width the quest text wraps at, in HTML pixels (the side panel is narrow). */
	private static final int QUEST_TEXT_WIDTH = 140;
	private static final Color IN_PROGRESS = new Color(255, 200, 70);

	/**
	 * The quests this boss needs, each with everything to do before it, in order. Shows how far
	 * you are when logged in; click any quest to open its guide on the wiki.
	 */
	private void addQuests(BossSetup setup)
	{
		BossQuests data = plugin.getBossQuests();
		List<BossQuests.Req> reqs = data.forBoss(setup.getBoss());
		if (reqs.isEmpty())
		{
			return;
		}

		// the whole to-do list: each needed quest after the quests it needs, nothing twice
		LinkedHashSet<String> all = new LinkedHashSet<>();
		for (BossQuests.Req r : reqs)
		{
			all.addAll(data.lineFor(r.getQuest()));
			all.add(r.getQuest());
		}
		int done = 0;
		boolean known = false;
		for (String q : all)
		{
			QuestState s = plugin.getQuestState(q);
			known |= s != null;
			if (s == QuestState.FINISHED)
			{
				done++;
			}
		}

		list.add(UiUtil.header("Quests needed"));
		String summary = !known ? all.size() + (all.size() == 1 ? " quest" : " quests") + " · log in to see your progress"
			: done == all.size() ? "All done"
			: done + " of " + all.size() + " done · click a quest for its guide";
		JLabel top = UiUtil.label(summary, known && done == all.size() ? UiUtil.PROFIT : UiUtil.MUTED, false);
		top.setBorder(new EmptyBorder(0, 2, 4, 2));
		UiUtil.addRow(list, top);

		for (BossQuests.Req r : reqs)
		{
			QuestState state = plugin.getQuestState(r.getQuest());
			UiUtil.addRow(list, questRow(r.getQuest(), r.getNote(), state, true, 0));
			// once the quest itself is done there's no point listing what led up to it
			if (state == QuestState.FINISHED)
			{
				continue;
			}
			int step = 0;
			for (String q : data.lineFor(r.getQuest()))
			{
				UiUtil.addRow(list, questRow(q, "", plugin.getQuestState(q), false, ++step));
			}
		}
	}

	/** The "show the way" button: there when this copy does boss routes and knows where the boss is. */
	private void showWayButton(BossSetup setup)
	{
		Places.Place p = setup == null ? null : plugin.getPlaces().find("boss", setup.getBoss());
		boolean perks = plugin.canRoutePerks();
		way.setVisible(p != null && (perks || plugin.routePerkHint() != null));
		way.setEnabled(p != null && perks);
		way.setToolTipText(p == null ? null : !perks ? plugin.routePerkHint()
			: p.getNote().isEmpty() ? "Draws the route on the map" : p.getNote());
	}

	private JLabel questRow(String quest, String note, QuestState state, boolean main, int step)
	{
		String mark = state == QuestState.FINISHED ? "&#10003; " : step > 0 ? step + ". " : "";
		StringBuilder sb = new StringBuilder("<html><div style='width:").append(QUEST_TEXT_WIDTH).append("px'>")
			.append(main ? "<b>" : "").append(mark).append(esc(quest)).append(main ? "</b>" : "");
		if (state == QuestState.IN_PROGRESS)
		{
			sb.append(" (started)");
		}
		if (!note.isEmpty())
		{
			sb.append("<br><i>").append(esc(note)).append("</i>");
		}
		sb.append("</div></html>");

		Color color = state == QuestState.FINISHED ? UiUtil.PROFIT : state == QuestState.IN_PROGRESS ? IN_PROGRESS
			: main ? Color.WHITE : UiUtil.MUTED;
		JLabel row = UiUtil.label(sb.toString(), color, false);
		row.setBorder(new EmptyBorder(1, main ? 2 : 10, 1, 2));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText("Click for the route to where " + quest + " starts, or its guide on the OSRS Wiki");
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				JPopupMenu menu = new JPopupMenu();
				JMenuItem go = new JMenuItem("Show the way to the start");
				go.addActionListener(a -> plugin.routeToQuest(quest));
				menu.add(go);
				JMenuItem guide = new JMenuItem("Open the wiki guide");
				guide.addActionListener(a -> LinkBrowser.browse(BossQuests.wikiUrl(quest)));
				menu.add(guide);
				menu.show(row, e.getX(), e.getY());
			}
		});
		return row;
	}

	private static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static long cost(GearPricer.Price p)
	{
		return p != null && p.isTradeable() ? p.getCost() : 0;
	}

	private static String tooltip(List<String> alts, GearPricer.Price p)
	{
		StringBuilder sb = new StringBuilder("<html>");
		sb.append(alts.size() > 1 ? "Equally good options:<br>" : "");
		for (String a : alts)
		{
			sb.append("• ").append(a.replace("&", "&amp;")).append("<br>");
		}
		if (p.isTradeable())
		{
			sb.append("Cheapest: ").append(p.getName()).append(" ≈ ").append(UiUtil.gp(p.getCost())).append(" gp");
		}
		if (p.getNote() != null)
		{
			sb.append("<br>").append(p.getNote());
		}
		return sb.append("</html>").toString();
	}

	private static JLabel stat()
	{
		return UiUtil.label("-", Color.WHITE, true);
	}

	private static JPanel box(String title, JLabel value)
	{
		JPanel p = new JPanel(new GridLayout(2, 1));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(4, 6, 4, 6));
		p.add(UiUtil.label(title, UiUtil.MUTED, false));
		p.add(value);
		return p;
	}

	private void repaintList()
	{
		list.revalidate();
		list.repaint();
	}
}

package com.moneymaker.ui;

import com.moneymaker.MoneyMakerConfig;
